import { useEffect, useState } from "react";
import { getComments } from "./api";

export default function useComments(slug) {
  const [comments, setComments] = useState([]);
  const [error, setError] = useState(null);

  useEffect(() => {
    const controller = new AbortController();

    setComments([]);
    setError(null);

    getComments(slug, { signal: controller.signal })
      .then((nextComments) => {
        if (!controller.signal.aborted) {
          setComments(nextComments);
        }
      })
      .catch((err) => {
        if (err?.name === "AbortError") return;
        setError(err?.message ?? "Failed to load comments");
      });

    return () => controller.abort();
  }, [slug]);

  return { comments, error };
}

import CommentRow from "./CommentRow";
import useComments from "./useComments";

function CommentFeed({ slug }) {
  const { comments, error } = useComments(slug);

  if (error) return <p className="error">{error}</p>;
  if (comments.length === 0) return null;

  return (
    <div className="feed">
      {comments.map((comment) => (
        <CommentRow key={comment.id} {...comment} />
      ))}
    </div>
  );
}

export default CommentFeed;

const express = require("express");
const cors = require("cors");
const { sequelize } = require("./models");
const { getCommentsBySlug, seedDemoData } = require("./commentService");

const PORT = 3001;
const app = express();

app.use(cors());

app.get("/api/articles/:slug/comments", async (req, res) => {
  try {
    const comments = await getCommentsBySlug(req.params.slug);
    if (!comments) {
      return res.status(404).json({ error: "not_found" });
    }

    res.json({ comments });
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: "server_error" });
  }
});

(async () => {
  try {
    await sequelize.sync();
    await seedDemoData();
    app.listen(PORT, () =>
      console.log(`Server running on http://localhost:${PORT}`),
    );
  } catch (error) {
    console.error("Unable to start:", error);
    process.exit(1);
  }
})();

const { User, Article, Comment } = require("./models");

const SEED = {
  username: "u1",
  slug: "a1",
  comments: ["c1", "c2"],
};

const COMMENT_INCLUDE = [
  { model: User, as: "author", attributes: ["username"] },
];

async function seedDemoData() {
  const [user] = await User.findOrCreate({
    where: { username: SEED.username },
    defaults: { username: SEED.username },
  });

  const [article] = await Article.findOrCreate({
    where: { slug: SEED.slug },
    defaults: { slug: SEED.slug, userId: user.id },
  });

  const count = await Comment.count({ where: { articleId: article.id } });
  if (count === 0) {
    await Comment.bulkCreate(
      SEED.comments.map((body) => ({
        body,
        articleId: article.id,
        userId: user.id,
      })),
    );
  }
}

async function getCommentsBySlug(slug) {
  const article = await Article.findOne({ where: { slug } });
  if (!article) {
    return null;
  }

  return article.getComments({
    include: COMMENT_INCLUDE,
  });
}

module.exports = {
  getCommentsBySlug,
  seedDemoData,
};

